// Ping each target, retry once on anything other than HTTP 200, track response time + state
const TARGETS = [
  { name: 'Conduit home page', url: 'https://realworld.svelte.dev/' },
  { name: 'Conduit article page', url: 'https://realworld.svelte.dev/article/introduction-to-machine-learning-for-developers' },
];
const TIMEOUT_MS = 10000;      // treat slower than this as a failure
const RETRY_DELAY_MS = 3000;   // wait before the single retry
const REMINDER_EVERY = 12;     // while still down, remind every 12 checks (~1 hour)

const sd = $getWorkflowStaticData('global');   // persists only in active (published) runs
sd.stats = sd.stats || {};
sd.streak = sd.streak || {};

const ping = async (url) => {
  const t0 = Date.now();
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET', url, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: TIMEOUT_MS,
    });
    return { status: res.statusCode, ms: Date.now() - t0, error: null };
  } catch (e) {
    return { status: 0, ms: Date.now() - t0, error: String(e.message || e).slice(0, 150) };
  }
};

const check = async (t) => {
  let r = await ping(t.url);
  let attempts = 1;
  if (r.status !== 200) {
    await new Promise(res => setTimeout(res, RETRY_DELAY_MS));
    r = await ping(t.url);
    attempts = 2;
  }
  return { ...t, ...r, attempts, ok: r.status === 200 };
};

const results = await Promise.all(TARGETS.map(check));

return results.map(r => {
  const st = sd.stats[r.name] = sd.stats[r.name] || { checks: 0, failures: 0, totalMs: 0, maxMs: 0 };
  st.checks++; st.totalMs += r.ms; st.maxMs = Math.max(st.maxMs, r.ms);
  if (!r.ok) st.failures++;

  const prev = sd.streak[r.name] || 0;
  const streak = r.ok ? 0 : prev + 1;
  sd.streak[r.name] = streak;

  let notify = null, message = '';
  const detail = r.error ? 'error: ' + r.error : 'HTTP ' + r.status;
  if (!r.ok && (streak === 1 || streak % REMINDER_EVERY === 0)) {
    notify = 'down';
    message = '🚨 **DOWN: ' + r.name + '**\n' + r.url + '\nResult: ' + detail + ' after ' + r.attempts +
      ' attempts (last try ' + r.ms + ' ms)\nConsecutive failed checks: ' + streak + '\nTime: ' + new Date().toISOString();
  } else if (r.ok && prev > 0) {
    notify = 'recovered';
    message = '✅ **RECOVERED: ' + r.name + '**\nHTTP 200 in ' + r.ms + ' ms after ' + prev + ' failed checks\nTime: ' + new Date().toISOString();
  }
  return { json: { name: r.name, url: r.url, status: r.status, ms: r.ms, ok: r.ok, attempts: r.attempts,
                   notify, shouldNotify: notify !== null, message } };
});

// Daily summary from stats collected by the 5-minute monitor, then reset the counters
const sd = $getWorkflowStaticData('global');
const stats = sd.stats || {};
const names = Object.keys(stats);
let msg;
if (!names.length) {
  msg = '📊 **Daily uptime summary**\nNo checks recorded yet.';
} else {
  const lines = names.map(n => {
    const s = stats[n];
    const up = ((s.checks - s.failures) / s.checks * 100).toFixed(1);
    const avg = Math.round(s.totalMs / s.checks);
    return '- **' + n + '**: ' + up + '% up (' + (s.checks - s.failures) + '/' + s.checks + ' checks), avg ' + avg + ' ms, slowest ' + s.maxMs + ' ms';
  });
  msg = '📊 **Daily uptime summary**\n' + lines.join('\n');
}
sd.stats = {};
return [{ json: { content: msg } }];
